@GetMapping("/{id}")
public ResponseEntity<$TYPE$DtoResponse> findById(@PathVariable Long id) {
  return ResponseEntity.ok(service.findById(id));
}

@PostMapping
public ResponseEntity<DtoResponse> create(
        @Valid @RequestBody DtoRequest request) {

    return ResponseEntity.status(HttpStatus.CREATED)
            .body(service.save(request));
}

@PutMapping("/{id}")
public ResponseEntity<$Type1$DtoResponse> update(
        @PathVariable Long id,
        @Valid @RequestBody $Type2$DtoRequest request) {

    return ResponseEntity.ok(service.update(id, request));
}

@DeleteMapping("/{id}")
public ResponseEntity<Void> delete(@PathVariable Long id) {
    service.delete(id);
    return ResponseEntity.noContent().build();
}

@GetMapping("/{id}/$PATH$")
public ResponseEntity<List<DtoResponse>> retrieveById(
        @PathVariable Long id) {

    return ResponseEntity.ok(service.findByPath(id));
}

@GetMapping
public ResponseEntity<List<DtoResponse>> find(
        @RequestParam(required = false) String param1) {

    return ResponseEntity.ok(
            service.find(param1)
    );
}

@PostMapping("/{id}/$PATH$")
public ResponseEntity<$Type1$DtoResponse> create(
  @PathVariable Long id,
  @Valid @RequestBody $Type2$DtoRequest request) {

  return ResponseEntity
    .status(HttpStatus.CREATED)
    .body(service.create(id, request));
}

@PatchMapping("/{id}")
public ResponseEntity<DtoResponse> updatePartial(
        @PathVariable Long id,
        @Valid @RequestBody DtoRequest request) {

    return ResponseEntity.ok(
            service.updatePartial(id, request)
    );
}

@DeleteMapping
public ResponseEntity<Void> delete(
        @RequestParam Long paramquery1) {

    service.delete(paramquery1);

    return ResponseEntity.noContent().build();
}

@GetMapping("/search")
public ResponseEntity<List<DtoResponse>> search(
        @RequestParam(required = false) String name,
        @RequestParam(required = false) String email,
        @RequestParam(required = false) String status) {

    return ResponseEntity.ok(
            service.search(name, email, status)
    );
}
